+import { createReadStream, existsSync, readFileSync, statSync } from 'node:fs';
+import { createServer, IncomingMessage, ServerResponse } from 'node:http';
+import { extname, join, normalize, resolve } from 'node:path';
+import chokidar, { FSWatcher } from 'chokidar';
+import { WebSocketServer } from 'ws';
+import { BuildOptions, createBuildPipeline } from './generator';
+import type { Plugin, PluginContext } from './plugin';
+
+const liveReloadScript = `<script>(() => { const socket = new WebSocket((location.protocol === 'https:' ? 'wss://' : 'ws://') + location.host + '/__ssg_live_reload'); socket.addEventListener('message', () => location.reload()); })();</script>`;
+const mimeTypes: Record<string, string> = { '.css': 'text/css; charset=utf-8', '.html': 'text/html; charset=utf-8', '.js': 'text/javascript; charset=utf-8', '.json': 'application/json; charset=utf-8', '.svg': 'image/svg+xml' };
+
+export interface ServeOptions extends BuildOptions { port?: number; }
+export interface DevelopmentServer { close(): Promise<void>; port: number; }
+
+export function injectLiveReload(html: string): string {
+  return /<\/body\s*>/i.test(html) ? html.replace(/<\/body\s*>/i, `${liveReloadScript}</body>`) : `${html}${liveReloadScript}`;
+}
+
+function serveFile(request: IncomingMessage, response: ServerResponse, outputDir: string): void {
+  const urlPath = decodeURIComponent(new URL(request.url ?? '/', 'http://localhost').pathname);
+  const root = resolve(outputDir);
+  let filePath = resolve(root, normalize(urlPath === '/' ? 'index.html' : urlPath.replace(/^\/+/, '')));
+  if (!filePath.startsWith(`${root}/`) && filePath !== root) return void response.writeHead(403).end('Forbidden');
+  if (existsSync(filePath) && statSync(filePath).isDirectory()) filePath = join(filePath, 'index.html');
+  if (!existsSync(filePath) || !statSync(filePath).isFile()) return void response.writeHead(404).end('Not found');
+  const type = mimeTypes[extname(filePath).toLowerCase()] ?? 'application/octet-stream';
+  response.writeHead(200, { 'content-type': type });
+  if (extname(filePath).toLowerCase() === '.html') response.end(injectLiveReload(readFileSync(filePath, 'utf8')));
+  else createReadStream(filePath).pipe(response);
+}
+
+export function createDevServerPlugin(port = 3000): Plugin {
+  let server: ReturnType<typeof createServer> | undefined;
+  let watcher: FSWatcher | undefined;
+  let webSockets: WebSocketServer | undefined;
+  let rebuildTimer: NodeJS.Timeout | undefined;
+  return {
+    onStart(context: PluginContext) {
+      if (context.command !== 'serve') return;
+      server = createServer((request, response) => serveFile(request, response, context.options.outputDir));
+      webSockets = new WebSocketServer({ noServer: true });
+      server.on('upgrade', (request, socket, head) => {
+        if (new URL(request.url ?? '/', 'http://localhost').pathname !== '/__ssg_live_reload') return socket.destroy();
+        webSockets?.handleUpgrade(request, socket, head, (client) => webSockets?.emit('connection', client, request));
+      });
+      watcher = chokidar.watch([context.options.contentDir, context.options.templatesDir], { ignoreInitial: true });
+      watcher.on('all', () => {
+        clearTimeout(rebuildTimer);
+        rebuildTimer = setTimeout(() => { try { const pages = context.rebuild(); console.log(`Built ${pages.length} page${pages.length === 1 ? '' : 's'}. Reloading browsers.`); for (const client of webSockets?.clients ?? []) client.send('reload'); } catch (error) { console.error(error instanceof Error ? error.message : error); } }, 50);
+      });
+      server.listen(port, 'localhost', () => console.log(`Serving ${context.options.outputDir} at http://localhost:${port}`));
+    },
+    async onEnd() {
+      clearTimeout(rebuildTimer);
+      await watcher?.close();
+      for (const client of webSockets?.clients ?? []) client.close();
+      if (server?.listening) await new Promise<void>((resolveClose, rejectClose) => server?.close((error) => error ? rejectClose(error) : resolveClose()));
+    },
+  };
+}
+
+export const DevServerPlugin = createDevServerPlugin;
+
+export function startServer({ port = 3000, ...options }: ServeOptions = {}): DevelopmentServer {
+  const pipeline = createBuildPipeline(options, 'serve');
+  pipeline.build();
+  return { port, close: () => pipeline.end() };
+}

